import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

// React
import React, { useState, useEffect } from "react";
import { useHistory } from "react-router-dom";
import moment from "moment";
import { SingleDatePicker } from "react-dates";
import { FormattedMessage } from "react-intl";
import Loader from "react-loader-spinner";

// Redux
import { connect } from "react-redux";
import { fetchAffiliates, fetchAffiliatesNamesAndCodes } from "../../actions/affiliates";
import { fxhistory, updateFxHistory, openModal, getAllCurrencyCodes, openAlert, closeAlert } from "../../actions/utils";

// Components
import {
	Alert,
	Button,
	Card,
	CardBody,
	CardHeader,
	Col,
	Form,
	FormGroup,
	Input,
	Label,
	Modal,
	ModalBody,
	ModalFooter,
	ModalHeader,
	Row,
	Table,
} from "reactstrap";

import PostingTableHeader from "../../components/PostingTableHeader";
import AddRates from "../../components/AddRates";

// query string
const queryString = require("query-string");

const History = ({
	// action creators
	fetchAffiliates,
	fxhistory,
	updateFxHistory,
	fetchAffiliatesNamesAndCodes,
	openModal,
	getAllCurrencyCodes,
	openAlert,
	closeAlert,
	// query string props
	location                     : { search: queryParams },
	// state from props
	currentAffiliate,
	allAffiliates,
	allAffiliatesNamesAndCodes,
	exchangeRates,
	exchangeRatesError,
	allCurrencyCodes,
	allCurrencyCodesError,
	alertError,
	addRatesError,
}) => {
	// QUERY STRING VARIABLES
	const history = useHistory();
	let { date: settlementDate } = queryString.parse(queryParams);

	// State
	const [ focused, setFocused ] = useState(false);
	const [ startDate, setStartDate ] = useState(moment(settlementDate));

	useEffect(
		() => {
			fxhistory(queryParams);
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	const [ item, setItem ] = useState({});
	const [ buyRate, setBuyRate ] = useState("");
	const [ sellRate, setSellRate ] = useState("");
	const [ midRate, setMidRate ] = useState("");
	const [ isLoading, setIsLoading ] = useState(false);
	const [ error, setError ] = useState("");
	const [ showModal, setShowModal ] = useState(false);

	useEffect(
		() => {
			setIsLoading(false);
			setShowModal(false);
		},
		[ exchangeRates ],
	);

	useEffect(
		() => {
			setStartDate(moment(settlementDate));
			fxhistory(queryParams);
			getAllCurrencyCodes();
		},
		[ queryParams ],
	);

	const handleSubmitDate = (selectedDate) => {
		let settlementDate = moment(selectedDate).format("YYYY-MM-DD");
		history.push(`/affiliate/exchange-rates/?date=${settlementDate}`);
	};

	const handleSubmit = (item, sellRate, buyRate, midRate) => {
		// handle submit of modal form and calls updateFxHistory action creator
		if (!sellRate || !buyRate || !midRate || error) return; // return stop submit if there are errors
		// setState({ isLoading: true });
		updateFxHistory(item, sellRate, buyRate, midRate);
	};

	const toggle = (item) => {
		// close update fx history modal and set state with relevant data to update
		setShowModal(!showModal);
		setItem(item);
		setSellRate(item.sellRate);
		setBuyRate(item.buyRate);
		setMidRate(item.midRate);
		setError(false);
	};

	const SettlementRateHeader = [
		"Settlement Date",
		"From Currency Code",
		"To Currency Code",
		"Buy Rate",
		"Mid Rate",
		"Sell Rate",
		"Update",
	];

	return (
		<div className='animated fadeIn'>
			<Row>
				<Col>
					<Alert isOpen={alertError ? true : false} toggle={closeAlert} color='danger'>
						{(addRatesError &&
							addRatesError.response &&
							addRatesError.response.data &&
							addRatesError.response.data.message) ||
							"A rate with this currency code for this date already exists"}
					</Alert>

					<Card>
						{/* Update fx history modal below */}
						<Modal isOpen={showModal} toggle={toggle}>
							<ModalHeader toggle={toggle}>
								<FormattedMessage id='UPDATE EXCHANGE RATE' defaultMessage='UPDATE EXCHANGE RATE' />
							</ModalHeader>

							<ModalBody>
								<p>
									<strong>
										<FormattedMessage id='SETTLEMENT DATE:' defaultMessage='SETTLEMENT DATE:' />
									</strong>{" "}
									{item.settlementDate}
								</p>

								<p>
									<strong>
										<FormattedMessage id='EXCHANGE CURRENCY:' defaultMessage='EXCHANGE CURRENCY:' />
									</strong>{" "}
									From {item.fromCurrencyCode} to {item.toCurrencyCode}
								</p>
								<Form>
									<article className={"text-danger"}>
										{error && (
											<FormattedMessage id='Invalid input!' defaultMessage='Invalid input!' />
										)}
									</article>
									<FormGroup row>
										<Label for='Buy Rate' sm={4}>
											<FormattedMessage id='Buy Rate' defaultMessage='Buy Rate' />
										</Label>
										<Col sm={8}>
											<Input
												type='number'
												name='buyRate'
												id='buyRate'
												onChange={(e) => setBuyRate(e.target.value)}
												placeholder={buyRate}
											/>
										</Col>
									</FormGroup>
									<FormGroup row>
										<Label for='midRate' sm={4}>
											<FormattedMessage id='MID RATE' defaultMessage='MID RATE' />
										</Label>
										<Col sm={8}>
											<Input
												type='number'
												name='midRate'
												id='midRate'
												onChange={(e) => setMidRate(e.target.value)}
												placeholder={midRate}
											/>
										</Col>
									</FormGroup>
									<FormGroup row>
										<Label for='sellRate' sm={4}>
											<FormattedMessage id='SELL RATE' defaultMessage='SELL RATE' />
										</Label>
										<Col sm={8}>
											<Input
												type='number'
												name='sellRate'
												id='sellRate'
												onChange={(e) => setSellRate(e.target.value)}
												placeholder={sellRate}
											/>
										</Col>
									</FormGroup>
								</Form>
							</ModalBody>

							<ModalFooter>
								{!isLoading && (
									<div>
										<Button
											type='button'
											className={"mx-1"}
											color='primary'
											onClick={() => handleSubmit(item, sellRate, buyRate, midRate)}
										>
											<FormattedMessage id='Update' defaultMessage='Update' />
										</Button>
										<Button className={"mx-1"} color='danger' onClick={toggle}>
											<FormattedMessage id='Cancel' defaultMessage='Cancel' />
										</Button>
									</div>
								)}{" "}
								{isLoading && (
									<Loader
										type='ThreeDots'
										color='green'
										height={80}
										width={80}
										style={{ textAlign: "center", padding: "6px" }}
									/>
								)}
							</ModalFooter>
						</Modal>
						<AddRates settlementDate={settlementDate} currencyCodes={allCurrencyCodes} />

						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									{settlementDate}
									<FormattedMessage
										id=' Historical Rates Table'
										defaultMessage=' Historical Rates Table'
									/>
								</React.Fragment>
							</strong>

							<div className={"d-flex justify-content-end align-items-center w-50"}>
								<React.Fragment>
									<React.Fragment>
										<SingleDatePicker
											showDefaultInputIcon={true}
											date={startDate} // momentPropTypes.momentObj or null
											onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
											focused={focused} // PropTypes.bool
											onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
											id='your_unique_id' // PropTypes.string.isRequired,
											isOutsideRange={() => false}
											numberOfMonths={1}
										/>
										<Button
											style={{
												padding                : "9px",
												borderTopLeftRadius    : "0px",
												borderBottomLeftRadius : "0px",
											}}
											className={"btn-sm mx-1"}
											onClick={() => handleSubmitDate(startDate)}
											color='primary'
										>
											{" "}
											<FormattedMessage id='Submit' defaultMessage='Submit' />
										</Button>
									</React.Fragment>

									<Button
										style={{
											padding : "9px",
										}}
										onClick={openModal}
										type='button'
										className={"float-right mb-0 btn-sm mx-1 "}
										color='success'
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-plus' />&nbsp;
											<FormattedMessage id='Add Rates' defaultMessage='Add Rates' />
										</span>
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!exchangeRatesError &&
							!exchangeRates && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle Errors */}
							{exchangeRates &&
							!exchangeRatesError &&
							exchangeRates.length === 0 && (
								<article className='d-flex justify-content-center align-items-center'>
									<p className='text-center text-danger'>
										<FormattedMessage
											id={"There are no exchanges rates for this date! Add rate and tryagain!"}
											defaultMessage={
												"There are no exchanges rates for this date! Add rate and tryagain!"
											}
										/>
									</p>
								</article>
							)}

							{/* Handle Errors */}
							{!exchangeRates &&
							exchangeRatesError &&
							exchangeRatesError.response &&
							exchangeRatesError.response.data && (
								<article className='d-flex justify-content-center align-items-center'>
									<p className='text-center text-danger'>
										<FormattedMessage
											id={exchangeRatesError.response.data.message}
											defaultMessage={exchangeRatesError.response.data.message}
										/>
									</p>
								</article>
							)}

							{exchangeRates &&
							exchangeRates.length > 0 && (
								<Table
									hover
									bordered
									striped
									responsive
									size='sm'
									className='table-outline mb-0 d-sm-table'
								>
									<thead>
										<PostingTableHeader headerType={"array"} headerPayload={SettlementRateHeader} />
									</thead>

									<tbody>
										{exchangeRates.map((item, index) => {
											return (
												<tr key={item.id ? item.id : index}>
													<td>{item.settlementDate}</td>
													<td>{item.fromCurrencyCode}</td>
													<td>{item.toCurrencyCode}</td>
													<td>{item.buyRate ? item.buyRate : "N/A"}</td>
													<td>{item.midRate ? item.midRate : "N/A"}</td>
													<td>{item.sellRate ? item.sellRate : "N/A"}</td>
													<td>
														<button
															className={"btn btn-warning btn-block"}
															type={"button"}
															onClick={() => toggle(item)}
														>
															<FormattedMessage id='Edit' defaultMessage='Edit' />
														</button>
													</td>
												</tr>
											);
										})}
									</tbody>
								</Table>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		currentAffiliate           : state.fileSets,
		allAffiliates              : state.affiliates,
		allAffiliatesNamesAndCodes : state.affiliates.affiliatesNamesAndCodes,
		exchangeRates              : state.utils.exchangeRates,
		exchangeRatesError         : state.utils.exchangeRatesError,
		allCurrencyCodes           : state.utils.allCurrencyCodes,
		allCurrencyCodesError      : state.utils.allCurrencyCodesError,
		alertError                 : state.utils.alertError,
		addRatesError              : state.utils.addRatesError,
	};
};

export default connect(mapStateToProps, {
	fetchAffiliates,
	fxhistory,
	updateFxHistory,
	fetchAffiliatesNamesAndCodes,
	openModal,
	getAllCurrencyCodes,
	openAlert,
	closeAlert,
})(History);
