/* eslint react/no-multi-comp: 0, react/prop-types: 0 */

// React
import React, { useState } from "react";
import Select from "react-select";
import { FormattedMessage } from "react-intl";

// Redux
import { connect } from "react-redux";

// Components
import { closeModal, addFxHistoryRates } from "../actions/utils";
import { Button, Modal, ModalHeader, ModalFooter, Form, FormGroup, Label, Input, Col } from "reactstrap";

const AddRates = (props) => {
	const { className, settlementDate, currencyCodes, toggleModal, closeModal, addFxHistoryRates } = props;

	const [ fromCurrencyCode, setFromCurrencyCode ] = useState("");
	const [ toCurrencyCode, setToCurrencyCode ] = useState("");
	const [ buyRate, setBuyRate ] = useState("");
	const [ sellRate, setSellRate ] = useState("");
	const [ midRate, setMidRate ] = useState("");
	const [ isSellRateError, setIsSellRateError ] = useState(false);
	const [ isBuyRateError, setIsBuyRateError ] = useState(false);
	const [ isMidRateError, setIsMidRateError ] = useState(false);
	const [ isError, setIsError ] = useState(false);

	const handleSelectFromCurrencyCode = (selectedOption) => setFromCurrencyCode(selectedOption);
	const handleSelectToCurrencyCode = (selectedOption) => setToCurrencyCode(selectedOption);

	let allCurrencyCodes = [];
	allCurrencyCodes =
		currencyCodes &&
		currencyCodes.map((currCode) => {
			return { label: currCode, value: currCode };
		});

	const handleSubmit = () => {
		const addRateRegex = /^[1-9]\d{0,}(\.\d{1,3})?%?$/; //match decimals and non decimals don't allow leading zero or negative numbers

		if (
			// fromCurrencyCode.length === 0 &&
			sellRate.length === 0 &&
			midRate.length === 0 &&
			sellRate.length === 0
		) {
			setIsSellRateError(true);
			setIsMidRateError(true);
			setIsBuyRateError(true);
			setIsError(true);
			return;
		}

		if (addRateRegex.test(sellRate) !== true) {
			setIsSellRateError(true);
			setIsError(true);
			return;
		}

		if (addRateRegex.test(buyRate) !== true) {
			setIsBuyRateError(true);
			setIsError(true);
			return;
		}

		if (addRateRegex.test(midRate) !== true) {
			setIsMidRateError(true);
			setIsError(true);
			return;
		}

		const newRate = {
			settlementDate,
			fromCurrencyCode   : fromCurrencyCode.value,
			toCurrencyCode   : toCurrencyCode.value,
			sellRate,
			buyRate,
			midRate,
		};
		addFxHistoryRates(newRate);
		handleRefresh();
		closeModal();
	};

	const handleCloseModal = () => {
		setIsSellRateError(false);
		setIsMidRateError(false);
		setIsBuyRateError(false);
		closeModal();
	};

	const handleRefresh = () => {
		// Refresh All Errors
		setIsSellRateError(false);
		setIsMidRateError(false);
		setIsBuyRateError(false);
		setIsError(false);

		// Clear All fields
		setBuyRate("");
		setSellRate("");
        setMidRate("");
        setFromCurrencyCode("Select Currency Code")
        setToCurrencyCode("Select Currency Code")
	};

	return (
		<div>
			<Modal isOpen={toggleModal} className={className}>
				<ModalHeader>
					<FormattedMessage id='Add Rates ' defaultMessage='Add Rates ' />
					<small>
						<FormattedMessage id={` for ${settlementDate}`} defaultMessage={` for ${settlementDate}`} />
					</small>
				</ModalHeader>
				<Col xs={12}>
					<Form className={"d-flex flex-column justify-content-center py-3"}>
						<FormGroup>
							<span>From Currency Code</span>
							<Select
								className={"w-100 mt-1"}
								onChange={handleSelectFromCurrencyCode}
								value={fromCurrencyCode}
								options={allCurrencyCodes}
							/>
                        </FormGroup>
                        <FormGroup>
							<span>To Currency Code</span>
							<Select
								className={"w-100 mt-1"}
								onChange={handleSelectToCurrencyCode}
								value={toCurrencyCode}
								options={allCurrencyCodes}
							/>
						</FormGroup>
						<FormGroup>
							<Label for='Sell Rate'>
								<FormattedMessage id='Sell Rate' defaultMessage='Sell Rate' />
							</Label>
							<Input
								type='Sell Rate'
								name='Sell Rate'
								id='Sell Rate'
								placeholder='Enter Sell Rate'
								value={sellRate}
								onChange={(e) => setSellRate(e.target.value)}
								invalid={isSellRateError}
							/>
						</FormGroup>
						<FormGroup>
							<Label for='Buy Rate'>
								<FormattedMessage id='Buy Rate' defaultMessage='Buy Rate' />
							</Label>
							<Input
								type='Buy Rate'
								name='Buy Rate'
								id='Buy Rate'
								placeholder='Enter Buy Rate'
								value={buyRate}
								onChange={(e) => setBuyRate(e.target.value)}
								invalid={isBuyRateError}
							/>
						</FormGroup>
						<FormGroup>
							<Label for='Mid Rate'>
								<FormattedMessage id='Mid Rate' defaultMessage='Mid Rate' />
							</Label>
							<Input
								type='Mid Rate'
								name='Mid Rate'
								id='Mid Rate'
								placeholder='Enter Mid Rate'
								value={midRate}
								onChange={(e) => setMidRate(e.target.value)}
								invalid={isMidRateError}
							/>
						</FormGroup>
					</Form>
				</Col>
				<ModalFooter>
					{isError && (
						<Button color='warning' type='button' onClick={handleRefresh}>
							<FormattedMessage id='Refresh' defaultMessage='Refresh' />
						</Button>
					)}{" "}
					<Button color='success' type='button' onClick={handleSubmit}>
						<FormattedMessage id='Submit' defaultMessage='Submit' />
					</Button>{" "}
					<Button color='danger' onClick={handleCloseModal}>
						<FormattedMessage id='Cancel' defaultMessage='Cancel' />
					</Button>
				</ModalFooter>
			</Modal>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		toggleModal : state.utils.openModal,
	};
};

export default connect(mapStateToProps, { addFxHistoryRates, closeModal })(AddRates);
